from funcy import memoize, cache, reraise
from funcy.calc import SkipMemoization

for decorate in (memoize, memoize(), cache(60)):
    calls = []
    @decorate
    def f(*args, **kwargs):
        calls.append((args, kwargs))
        return len(calls)
    assert f(1, b=2, a=3) == f(1, a=3, b=2) == 1
    assert f(2) == 2
    memory = f.memory
    f.invalidate(1, a=3, b=2)
    f.invalidate(1, b=2, a=3)
    assert f(2) == 2
    assert f(1, a=3, b=2) == 3
    f.invalidate_all()
    assert f.memory is memory and not memory
    assert f(2) == 4
    assert f.skip is SkipMemoization

