original = ValueError('original')
seen = []
def transform(error):
    seen.append(error)
    return RuntimeError('converted: ' + str(error))

@reraise(ValueError, transform)
def fail():
    raise original
for invoke in (fail, fail):
    try:
        invoke()
    except RuntimeError as error:
        assert str(error) == 'converted: original'
        assert error.__cause__ is original
    else:
        raise AssertionError('No exception')
assert seen == [original, original]

class CallableError(RuntimeError):
    def __call__(self, error):
        raise AssertionError('Exception instances must not be called')

for into in (RuntimeError, RuntimeError('fixed'), CallableError('fixed'), transform):
    try:
        with reraise(ValueError, into):
            raise original
    except RuntimeError as error:
        assert error.__cause__ is original
        if isinstance(into, BaseException):
            assert error is into
        if into is RuntimeError:
            assert error.args == ()
    else:
        raise AssertionError('No exception')

seen[:] = []
with reraise(ValueError, transform):
    pass
assert not seen
try:
    with reraise(KeyError, transform):
        raise original
except ValueError as error:
